CREATE TABLE "Users" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar UNIQUE NOT NULL,
  "email" varchar UNIQUE NOT NULL,
  "password_hash" varchar NOT NULL,
  "creation_time" datetime NOT NULL
);

CREATE TABLE "Expense_Categories" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "user_id" int
);

CREATE TABLE "Expense_Transactions" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "amount" decimal NOT NULL,
  "title" varchar NOT NULL,
  "description" varchar,
  "category_id" int NOT NULL,
  "user_id" int NOT NULL
);

ALTER TABLE "Expense_Categories" ADD FOREIGN KEY ("user_id") REFERENCES "Users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Expense_Transactions" ADD FOREIGN KEY ("category_id") REFERENCES "Expense_Categories" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Expense_Transactions" ADD FOREIGN KEY ("user_id") REFERENCES "Users" ("id") DEFERRABLE INITIALLY IMMEDIATE;
);
